#!/usr/bin/env python3
"""Writes regmaps/zb_accel.yaml: the accelerator control map with its 16 coefficient registers (a loop, so a script).
    python3 designs/b64b_zedboard/gen_accel_map.py     then     python3 -m hwsw.regmap gen designs/b64b_zedboard/regmaps/zb_accel.yaml --out designs/b64b_zedboard/gen/regs
"""
from pathlib import Path

y = '''# regmap/1 (brief 64B): control and status of the stream accelerator (CRC-32 or a 16-tap FIR) fed and drained by an AXI DMA.
# Generated by gen_accel_map.py (the 16 coefficient registers are a loop); edit that, not this file.
regmap: 1
name: zb_accel
version: 0.1.0
summary: Control and status of the CRC-32 / FIR stream accelerator.
addr_width: 12
unmapped: split
registers:
- name: ID
  offset: 0x000
  summary: Block identity.
  fields:
  - {name: MAGIC, lsb: 16, width: 16, access: RO, const: 0x64B3, summary: fixed pattern 0x64B3}
  - {name: VERSION, lsb: 0, width: 16, access: RO, const: 0x0100, summary: register-map version 1.0}
- name: CTRL
  offset: 0x004
  summary: Mode; written while the block is idle.
  fields:
  - {name: MODE, lsb: 0, width: 1, access: RW, reset: 0, summary: "0 = CRC-32 of the stream, 1 = 16-tap FIR of the stream"}
- name: CMD
  offset: 0x008
  summary: Commands; reading returns 0.
  fields:
  - {name: START, lsb: 0, width: 1, access: W1P, summary: "arm the block for one packet: clear the CRC (or reset the FIR and load the coefficients) and start the job clock"}
- name: STATUS
  offset: 0x00C
  summary: Live state.
  fields:
  - {name: BUSY, lsb: 0, width: 1, access: RO, summary: armed and not yet finished}
  - {name: READY, lsb: 1, width: 1, access: RO, summary: the stream input is being accepted}
- name: JOB_CYCLES
  offset: 0x010
  summary: Fabric clocks from START to the last output beat of the last job.
  fields:
  - {name: VALUE, lsb: 0, width: 32, access: RO, summary: clocks}
- name: IN_BEATS
  offset: 0x014
  summary: Stream beats accepted in the last job.
  fields:
  - {name: VALUE, lsb: 0, width: 32, access: RO, summary: beats}
- name: OUT_BEATS
  offset: 0x018
  summary: Stream beats produced in the last job.
  fields:
  - {name: VALUE, lsb: 0, width: 32, access: RO, summary: beats}
- name: SCRATCH
  offset: 0x0FC
  summary: Free read/write word for bus tests.
  fields:
  - {name: VALUE, lsb: 0, width: 32, access: RW, reset: 0}
'''
for i in range(16):
    y += f'''- name: COEF{i}
  offset: 0x{0x40 + 4 * i:03X}
  summary: FIR coefficient h[{i}] (signed 12 bits), used at the next START in FIR mode.
  fields:
  - {{name: VALUE, lsb: 0, width: 12, access: RW, reset: 0, summary: "signed coefficient h[{i}]"}}
'''
Path(__file__).with_name("regmaps").joinpath("zb_accel.yaml").write_text(y)
